import React, { useState } from 'react';
import axios from 'axios';
import { useHistory } from 'react-router-dom';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const history = useHistory();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {
      // Si no hay backend, simulamos éxito cuando hay usuario y contraseña
      if (!axios) throw new Error('axios no disponible');
      const response = await axios.post('/api/login', { username, password });
      // Si la API responde con éxito, redirigimos
      if (response && response.status === 200) {
        history.push('/content');
      } else {
        setError('Credenciales inválidas');
      }
    } catch (err) {
      console.error('Error al iniciar sesión:', err);
      // Fallback: si no hay servidor, permitir acceso de prueba si se ingresan valores
      if (username && password) {
        history.push('/content');
      } else {
        setError('Error al iniciar sesión. Comprueba tus credenciales.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 400, margin: '0 auto' }}>
      <input aria-label="usuario" type="text" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="Usuario" />
      <input aria-label="contraseña" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Contraseña" />
      <button type="submit" disabled={loading}>{loading ? 'Entrando...' : 'Entrar'}</button>
      {error && <p style={{ color: 'red' }}>{error}</p>}
    </form>
  );
};

export default Login;
